-- MySQL script for Airline Flight Analytics dataset
CREATE DATABASE IF NOT EXISTS airline_analytics;
USE airline_analytics;

DROP TABLE IF EXISTS `airline_flight_analytics`;
CREATE TABLE `airline_flight_analytics` (
    `Flight_ID` VARCHAR(20) PRIMARY KEY,
    `Flight_Date` DATE,
    `Airline` VARCHAR(100),
    `Flight_Number` VARCHAR(20),
    `Origin_Airport` VARCHAR(100),
    `Destination_Airport` VARCHAR(100),
    `Origin_City` VARCHAR(80),
    `Destination_City` VARCHAR(80),
    `Distance_KM` INT,
    `Scheduled_Departure` TIME,
    `Scheduled_Arrival` TIME,
    `Actual_Departure` TIME NULL,
    `Actual_Arrival` TIME NULL,
    `Flight_Duration_Min` INT,
    `Departure_Delay_Min` INT,
    `Arrival_Delay_Min` INT,
    `Flight_Status` VARCHAR(50),
    `Cancelled` VARCHAR(5),
    `Cancellation_Reason` VARCHAR(100),
    `Total_Seats` INT,
    `Passengers` INT,
    `Load_Factor_Pct` DECIMAL(6,2),
    `Cabin_Class` VARCHAR(30),
    `Average_Ticket_Price` DECIMAL(12,2),
    `Ticket_Revenue` BIGINT,
    `Baggage_Revenue` BIGINT,
    `Ancillary_Revenue` BIGINT,
    `Total_Revenue` BIGINT,
    `Operating_Cost` BIGINT,
    `Profit` BIGINT,
    `Origin_Region` VARCHAR(30),
    `Destination_Region` VARCHAR(30),
    `Flight_Type` VARCHAR(30),
    `Booking_Channel` VARCHAR(50),
    `Demand_Level` VARCHAR(20)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

